// Excludes absolute URLs and placeholder shapes (`path/to/test.ts`, `<owner>`-style segments) that spec prose uses to document the link convention itself.
const NON_REPO_PATH_RE = /^[a-z][a-z0-9+.-]*:|^path(\/|#|$)|[<>]/i;
